import org.checkerframework.checker.nullness.qual.NonNull;
import org.checkerframework.checker.nullness.qual.Nullable;
import org.cloudburstmc.nbt.NbtMap;
import org.geysermc.paletter.annotation.Internal;
import org.geysermc.paletter.behaviour.BehaviourKey;
import org.geysermc.paletter.behaviour.BlockBehaviour;
import org.geysermc.paletter.behaviour.ItemBehaviour;
import org.geysermc.paletter.property.Properties;

/**
 * Behaviour values read from the component data BDS sends (or Paletter sends for custom content): one rule per key.
 * The same rules read vanilla wire data and custom components, so the tests check them against the vanilla dumps on
 * the data driven blocks that carry both. Scalar rules are the inferred rules of {@code data/model/mappings.json}
 * read backwards; the shapes are the hand-written {@link ShapeRules}.
 */
@Internal
public final class WireRules {
    private WireRules() {
    }

    /**
     * @return the add-on component names (e.g. {@code minecraft:friction}) a user sets to set the key; empty if the
     * component data does not carry the key
     */
    public static @NonNull List<String> components(@NonNull BehaviourKey<?> key) {
        if (key == BlockBehaviour.DESTROY_TIME) {
            return List.of("minecraft:destructible_by_mining");
        }
        if (key == BlockBehaviour.FRICTION) {
            return List.of("minecraft:friction");
        }
        if (key == BlockBehaviour.COLLISION_SHAPE) {
            return List.of("minecraft:collision_box", "minecraft:transformation");
        }
        if (key == BlockBehaviour.OUTLINE_SHAPE) {
            return List.of("minecraft:selection_box", "minecraft:transformation");
        }
        if (key == BlockBehaviour.LIGHT_EMISSION) {
            return List.of("minecraft:light_emission");
        }
        if (key == BlockBehaviour.LIGHT_DAMPENING) {
            return List.of("minecraft:light_dampening");
        }
        if (key == ItemBehaviour.MAX_STACK_SIZE) {
            return List.of("minecraft:max_stack_size");
        }
        if (key == ItemBehaviour.MAX_DAMAGE) {
            return List.of("minecraft:durability");
        }
        if (key == ItemBehaviour.ATTACK_DAMAGE) {
            return List.of("minecraft:damage");
        }
        if (key == ItemBehaviour.USE_DURATION) {
            return List.of("minecraft:use_modifiers");
        }
        if (key == ItemBehaviour.USE_ANIMATION) {
            return List.of("minecraft:use_animation");
        }
        return List.of();
    }

    /**
     * @param properties the properties of a block state (permutations applied) or an item
     * @return the value, or null if the component data does not say
     */
    public static <T> @Nullable T value(@NonNull BehaviourKey<T> key,
            @NonNull Properties properties) {
        return key.type().cast(read(key, properties));
    }

    private static @Nullable Object read(BehaviourKey<?> key, Properties properties) {
        if (key == BlockBehaviour.DESTROY_TIME) {
            // minecraft:destructible_by_mining seconds_to_destroy -> minecraft:destructible_by_mining.value (identity): read back
            return floatOf(properties.component("minecraft:destructible_by_mining"), "value");
        }
        if (key == BlockBehaviour.FRICTION) {
            // minecraft:friction (value form) -> minecraft:friction.value (identity): read back
            // engine = 1.0 - component, measured by behaviour-probe (data/bds/1.26.63.1/behaviour-probe/capture.json friction.components)
            Float value = floatOf(properties.component("minecraft:friction"), "value");
            return value == null ? null : 1.0f - value;
        }
        if (key == BlockBehaviour.COLLISION_SHAPE) {
            return ShapeRules.collisionShape(properties);
        }
        if (key == BlockBehaviour.OUTLINE_SHAPE) {
            return ShapeRules.outlineShape(properties);
        }
        if (key == BlockBehaviour.LIGHT_EMISSION) {
            // minecraft:light_emission (value form) -> minecraft:light_emission.emission (identity): read back
            return intOf(properties.component("minecraft:light_emission"), "emission");
        }
        if (key == BlockBehaviour.LIGHT_DAMPENING) {
            // minecraft:light_dampening (value form) -> minecraft:light_dampening.lightLevel (identity): read back
            return intOf(properties.component("minecraft:light_dampening"), "lightLevel");
        }
        if (key == ItemBehaviour.MAX_STACK_SIZE) {
            // minecraft:max_stack_size value -> item_properties.max_stack_size (identity): the engine's item property, read as sent
            return intOf(properties.component("item_properties"), "max_stack_size");
        }
        if (key == ItemBehaviour.MAX_DAMAGE) {
            // minecraft:durability max_durability -> minecraft:durability.max_durability (identity): read back
            return intOf(properties.component("minecraft:durability"), "max_durability");
        }
        if (key == ItemBehaviour.ATTACK_DAMAGE) {
            // minecraft:damage value -> item_properties.damage (identity): the engine's item property, read as sent
            return intOf(properties.component("item_properties"), "damage");
        }
        if (key == ItemBehaviour.USE_DURATION) {
            // minecraft:use_modifiers use_duration -> item_properties.use_duration (linear, scale 20.0, offset 0.0): the engine's item property, read as sent
            return intOf(properties.component("item_properties"), "use_duration");
        }
        if (key == ItemBehaviour.USE_ANIMATION) {
            // minecraft:use_animation value -> item_properties.use_animation (constant): the engine's item property, read as sent
            return intOf(properties.component("item_properties"), "use_animation");
        }
        return null;
    }

    private static @Nullable Float floatOf(@Nullable NbtMap map, String field) {
        return map != null && map.get(field) instanceof Number number ? number.floatValue() : null;
    }

    private static @Nullable Integer intOf(@Nullable NbtMap map, String field) {
        return map != null && map.get(field) instanceof Number number ? number.intValue() : null;
    }
}
